def solve(inputs: dict) -> float:
    # Implement matrix power calculation with modular arithmetic
    M = inputs['matrix']
    n = inputs['power']
    mod = inputs['mod']

    from functools import reduce
    import numpy as np

    def matrix_mult(A, B):
        return (np.dot(A, B) % mod)

    result = reduce(matrix_mult, (M for _ in range(n)), np.eye(2, dtype=int))
    return np.sum(result)
